/* @lc app=leetcode id=2528 lang=kotlin */
class Solution { fun maxPower(stations: IntArray, r: Int, k: Int): Long = LongArray(stations.size + 1).also { pref -> stations.indices.forEach { i -> pref[i + 1] = pref[i] + stations[i] } }.let { pref -> { target: Long -> LongArray(stations.size + 1).let { diff -> var added = 0L var curAdd = 0L stations.indices.none { i -> (curAdd + diff[i]).also { curAdd = it }.let { (pref[minOf(stations.size, i + r + 1)] - pref[maxOf(0, i - r)] + curAdd).let { curPower -> if (curPower < target) (target - curPower).let { needed -> (added + needed).also { added = it } > k || (curAdd + needed).also { curAdd = it }.let { minOf(stations.size, i + 2 * r + 1).let { idx -> diff.set(idx, diff[idx] - needed).let { false } } } } else false } } } } }.let { check -> generateSequence(Triple(0L, pref.last() + k, 0L)) { (low, high, ans) -> if (low > high) null else ((low + high) / 2).let { mid -> if (check(mid)) Triple(mid + 1, high, mid) else Triple(low, mid - 1, ans) } }.last().third } } }